    flex-direction: column;
    align-items: center;
    justify-content: center;
    border-radius: 35px;
    transform: translateY(-130px);
}

/* Чтобы equal height не ломался */
.access-form {
    display: flex;
}

/* Убираем стандартные отступы WPBakery внутри карточки */
.access-form .wpb_content_element {
    margin-bottom: 15px;
}

/* У иконки обычно слишком большой отступ */
.access-form .vc_icon_element {
    margin-bottom: 15px;
}

/* Если нужно ещё компактнее */
.access-form h2,
.access-form h3,
.access-form h4 {
    margin-bottom: 10px;
}

/* Цвет надписи на кнопке */
.button-color a {color:#000000 !important;font-weight: bold;}

