<script>
document.addEventListener('DOMContentLoaded', function () {

    function getCookie(name) {
        let match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
        return match ? match[2] : null;
    }

    function setCookie(name, value, days) {
        let d = new Date();
        d.setTime(d.getTime() + (days*24*60*60*1000));
        document.cookie = name + "=" + value + "; expires=" + d.toUTCString() + "; path=/";
    }

    if (getCookie('subscriber_popup_shown')) {
        return;
    }

    let popup = document.getElementById('subscriber-popup');

    // показать через 3 секунды
    setTimeout(function () {
        popup.style.display = 'block';
        setTimeout(() => popup.classList.add('show'), 50);
    }, 3000);

    // закрытие по кнопке
    document.getElementById('subscriber-popup-close').addEventListener('click', function () {
        popup.classList.remove('show');
        setTimeout(() => popup.style.display = 'none', 400);
        setCookie('subscriber_popup_shown', '1', 7);
    });

});
</script>

